[MH3U_EventQuestFix_JP_v96]
moduleMatches = 0x348600A0

; The quest reader 0x02076B10 reads six text fields, one string each. A US/EU record has
; five strings per field, so everything after the first string is misread (the next
; "length" is text, the allocation fails, memset(NULL) crashes). Each string read now goes
; through _eqfRead. After the title, the two bytes at +2 tell the layouts apart:
;   Western: [next string's u32 length]      -> high half = 0
;   Japanese: [u16 number][u32 length]       -> low half of a non-empty text's length != 0
; On a Western record the four other languages of each field are read and dropped.
.origin = codecave

_eqfState:
.uint 0            ; +0 the reader object of the record being parsed
.uint 0            ; +4 1 = that record is in the Western layout

_eqfName:
li r6, 1
b _eqfRead
_eqfMore:
li r6, 0
_eqfRead:
mflr r0
stwu r1, -0x70(r1)
stw r0, 0x74(r1)
stw r29, 0x64(r1)
stw r30, 0x68(r1)
stw r31, 0x6C(r1)
mr r31, r3
mr r30, r6
bl 0x02D93868      ; the original read (r3 reader, r4 dest, r5 size)
lis r12, _eqfState@ha
addi r12, r12, _eqfState@l
cmpwi r30, 0
beq _eqfCheck
li r0, 0
lwz r10, 8(r31)    ; read position
lwz r11, 0xC(r31)  ; end of buffered data
addi r9, r10, 4
cmplw r9, r11
bgt _eqfStore
lwz r9, 4(r31)     ; buffer
add r9, r9, r10
lhz r9, 2(r9)
cmpwi r9, 0
bne _eqfStore
li r0, 1
_eqfStore:
stw r31, 0(r12)
stw r0, 4(r12)
_eqfCheck:
lwz r0, 0(r12)
cmplw r0, r31
bne _eqfDone
lwz r0, 4(r12)
cmpwi r0, 0
beq _eqfDone
li r30, 4
_eqfNext:
mr r3, r31
bl 0x02D93C88      ; u32 length
mr r29, r3
_eqfSkip:
cmpwi r29, 0
ble _eqfSkipped
mr r5, r29
cmpwi r5, 0x40
ble _eqfChunk
li r5, 0x40
_eqfChunk:
subf r29, r5, r29
mr r3, r31
addi r4, r1, 0x10
bl 0x02D93868
b _eqfSkip
_eqfSkipped:
addi r30, r30, -1
cmpwi r30, 0
bne _eqfNext
_eqfDone:
lwz r0, 0x74(r1)
lwz r29, 0x64(r1)
lwz r30, 0x68(r1)
lwz r31, 0x6C(r1)
mtlr r0
addi r1, r1, 0x70
blr

; Board summary: a Western host sends 5 titles + 5 objectives, JP expects 1 + 1.
; r3 = summary in wire order, its quest number is at r3-4.
_eqfBoard:
lhz r5, -4(r3)
lhz r6, 0x1E(r3)
cmplw r6, r5
beq _eqfBoardGo
lhz r6, 0x96(r3)
cmplw r6, r5
bne _eqfBoardGo
lhz r6, 0x1CE(r3)
lhz r7, 0x1D0(r3)
lhz r8, 0x1D2(r3)
lhz r9, 0x1D4(r3)
lhz r10, 0x1D6(r3)
lhz r11, 0x1D8(r3)
li r0, 0x3E
mtctr r0
addi r4, r3, 0x97
addi r12, r3, 0x1F
_eqfBoardCopy:
lbzu r0, 1(r4)
stbu r0, 1(r12)
bdnz _eqfBoardCopy
li r0, 0x17E
mtctr r0
addi r12, r3, 0x5F
li r0, 0
_eqfBoardClear:
stbu r0, 1(r12)
bdnz _eqfBoardClear
stb r0, 0x1D(r3)
stb r0, 0x5D(r3)
sth r5, 0x1E(r3)
sth r6, 0x5E(r3)
sth r7, 0x9E(r3)
sth r8, 0xDE(r3)
sth r9, 0xE0(r3)
sth r10, 0xE2(r3)
sth r11, 0x1DE(r3)
_eqfBoardGo:
b 0x02059CD4

; Event quests for the JP game. JP never reads the save's quest packs: 0x02165630 loads
; every quest once at boot, the list quest\quest (from quest00.arc), then quest\q_%05d for
; each number, into the table at this+0x48 (the number loaded ends in r27, then goes to
; 0x10314A40 for the rest of the game). After that loop, also load the list quest\revival
; and the quests it names. They are in no archive, so the resource manager reads them as
; loose files from this pack: nativeCafe/quest/revival.list and q_NNNNN.quest, which the
; launcher writes. The table is allocated 150 entries larger for them.
_eqfRevName:
.byte 0x71,0x75,0x65,0x73,0x74,0x5C,0x72,0x65,0x76,0x69,0x76,0x61,0x6C,0x00
.align 4

_eqfRevival:
lwz r3, 0(r30)            ; resource manager (r30 = 0x102CE7D4 since the loop)
lwz r12, 0(r3)
lwz r0, 0x64(r12)         ; getResource(dti, path, 1)
mtctr r0
lis r4, 0x1031
addi r4, r4, 0x1128       ; rQuestList
lis r5, _eqfRevName@ha
addi r5, r5, _eqfRevName@l
li r6, 1
bctrl
cmpwi r3, 0
beq _eqfRevEnd
lwz r28, 0x64(r3)         ; number of entries
lwz r26, 0x70(r3)         ; entry pointers
cmplwi r28, 150
ble _eqfRevCount
li r28, 150
_eqfRevCount:
li r29, 0
_eqfRevLoop:
cmplw r29, r28
bge _eqfRevEnd
slwi r12, r29, 2
lwzx r5, r12, r26
lwz r5, 4(r5)             ; quest_no
lis r4, 0x1002
addi r4, r4, 0x17C4       ; "quest\q_%05d"
addi r3, r1, 8
crxor 4*cr1+eq, 4*cr1+eq, 4*cr1+eq
bl 0x03124F74             ; sprintf
lwz r3, 0(r30)
lwz r12, 0(r3)
lwz r0, 0x64(r12)
mtctr r0
lis r4, 0x1031
addi r4, r4, 0x10C8       ; rQuestData
addi r5, r1, 8
li r6, 1
bctrl
cmpwi r3, 0
beq _eqfRevNext
lwz r7, 0x48(r31)
slwi r8, r27, 2
stwx r3, r8, r7
addi r27, r27, 1
_eqfRevNext:
addi r29, r29, 1
b _eqfRevLoop
_eqfRevEnd:
lwz r7, 0x48(r31)
slwi r8, r27, 2
li r0, 0
stwx r0, r8, r7           ; keep the table null-terminated
li r28, 0                 ; the code after the hook uses r28 as zero
lwz r11, 0x4C(r31)        ; the replaced instruction
b 0x021657A0

0x02076BC8 = bl _eqfName
0x02076C54 = bl _eqfMore
0x02076CF0 = bl _eqfMore
0x02076D80 = bl _eqfMore
0x02076E28 = bl _eqfMore
0x02076EAC = bl _eqfMore
0x0224EB84 = bl _eqfBoard
0x021656C4 = addi r4, r5, 0x25C   ; quest table: count + 1 + 150 entries
0x0216579C = b _eqfRevival


[MH3U_EventQuestFix_US_v32]
moduleMatches = 0x9D2F15E5

; The other direction. The US reader's string helper 0x02076B6C reads five strings per text
; field, so a JP record (one string per field) is misread and the quest is lost: the lookup
; by number then returns null and 0x02178F3C crashes. This replaces the helper at its six
; call sites. After the title, the same two bytes tell the layouts apart. On a JP record the
; one string is read and copied into all five language slots (each slot is freed on its own,
; so each needs its own allocation).
.origin = codecave

_eqfUState:
.uint 0            ; +0 the reader object of the record being parsed
.uint 0            ; +4 1 = that record is in the JP layout
.uint 0            ; +8 next text field
.uint 0            ; +C quest number

_eqfUName:
li r6, 1
b _eqfUStrs
_eqfUMore:
li r6, 0
_eqfUStrs:
stwu r1, -0x30(r1)
mflr r0
stmw r25, 0xC(r1)
stw r0, 0x34(r1)
mr r31, r5         ; reader
mr r29, r4         ; the five string slots
mr r26, r6         ; 1 = title field
li r28, 0          ; language
li r25, 0          ; 1 = JP layout
_eqfULoop:
cmpwi r28, 0
beq _eqfULen
cmpwi r25, 0
bne _eqfUAlloc     ; JP layout: same length as the first string
_eqfULen:
lwz r8, 0x14(r31)
lwz r9, 0x1C(r8)
mtctr r9
mr r3, r31
bctrl
mr r30, r3
_eqfUAlloc:
lis r12, 0x103D
lwz r12, 0x612C(r12)
lwz r10, 0(r12)
lwz r0, 0x3C(r10)
mtctr r0
mr r3, r12
li r5, 0x10
addi r4, r30, 1
bctrl
slwi r27, r28, 2
stwx r3, r29, r27
cmpwi r28, 0
beq _eqfURead
cmpwi r25, 0
beq _eqfURead
lwz r7, 0(r29)     ; JP layout: copy the first string
li r9, 0
_eqfUCopy:
cmpw r9, r30
bge _eqfUEnd
lbzx r0, r7, r9
stbx r0, r3, r9
addi r9, r9, 1
b _eqfUCopy
_eqfURead:
mr r4, r3
mr r3, r31
mr r5, r30
bl 0x02D93F10
_eqfUEnd:
lwzx r6, r29, r27
li r0, 0
stbx r0, r6, r30
cmpwi r28, 0
bne _eqfUNext
lis r12, _eqfUState@ha
addi r12, r12, _eqfUState@l
cmpwi r26, 0
beq _eqfUKnown
li r0, 0
lwz r10, 8(r31)    ; read position
lwz r11, 0xC(r31)  ; end of buffered data
addi r9, r10, 4
cmplw r9, r11
bgt _eqfUStore
lwz r9, 4(r31)     ; buffer
add r9, r9, r10
lhz r8, 2(r9)
cmpwi r8, 0
beq _eqfUStore     ; high half of the next length = Western
lbz r7, 0(r9)      ; quest number, little endian
lbz r8, 1(r9)
slwi r8, r8, 8
or r7, r7, r8
stw r7, 0xC(r12)
li r8, 0
stw r8, 8(r12)
li r0, 1
_eqfUStore:
stw r31, 0(r12)
stw r0, 4(r12)
_eqfUKnown:
lwz r0, 0(r12)
cmplw r0, r31
bne _eqfUNext
lwz r25, 4(r12)
_eqfUNext:
addi r28, r28, 1
cmpwi r28, 5
blt _eqfULoop
cmpwi r25, 0
beq _eqfUExit
lis r12, _eqfUState@ha
addi r12, r12, _eqfUState@l
lwz r4, 8(r12)
addi r0, r4, 1
stw r0, 8(r12)
lwz r5, 0xC(r12)
mr r3, r29
bl _eqfUText
_eqfUExit:
lwz r0, 0x34(r1)
mtlr r0
lmw r25, 0xC(r1)
addi r1, r1, 0x30
blr

; Board summary: a JP host sends 1 title + 1 objective, this game expects 5 + 5.
; r3 = summary in wire order, its quest number is at r3-4.
_eqfUBoard:
lhz r5, -4(r3)
lhz r6, 0x96(r3)
cmplw r6, r5
beq _eqfUBoardGo
lhz r6, 0x1E(r3)
cmplw r6, r5
bne _eqfUBoardGo
lhz r6, 0x5E(r3)
lhz r7, 0x9E(r3)
lhz r8, 0xDE(r3)
lhz r9, 0xE0(r3)
lhz r10, 0xE2(r3)
lhz r11, 0x1DE(r3)
li r0, 0
stb r0, 0x1D(r3)
stb r0, 0x5D(r3)
li r0, 0x3E
mtctr r0
addi r4, r3, 0x1F
addi r12, r3, 0x97
_eqfUBoardObj:
lbzu r0, 1(r4)
stbu r0, 1(r12)
bdnz _eqfUBoardObj
li r0, 0xF8
mtctr r0
addi r4, r3, 0x97
addi r12, r3, 0xD5
_eqfUBoardObj2:
lbzu r0, 1(r4)
stbu r0, 1(r12)
bdnz _eqfUBoardObj2
li r0, 0x78
mtctr r0
addi r4, r3, -1
addi r12, r3, 0x1D
_eqfUBoardTitle:
lbzu r0, 1(r4)
stbu r0, 1(r12)
bdnz _eqfUBoardTitle
sth r5, 0x96(r3)
sth r6, 0x1CE(r3)
sth r7, 0x1D0(r3)
sth r8, 0x1D2(r3)
sth r9, 0x1D4(r3)
sth r10, 0x1D6(r3)
sth r11, 0x1D8(r3)
mflr r0
stwu r1, -0x10(r1)
stw r0, 0x14(r1)
stw r3, 8(r1)
bl _eqfUBoardText
lwz r3, 8(r1)
lwz r0, 0x14(r1)
mtlr r0
addi r1, r1, 0x10
_eqfUBoardGo:
b 0x02059C44


; Replace a JP record's text with the Western text for that quest number, or with a UTF-8
; conversion. r3 = the five language slots (each holds the JP string), r4 = field, r5 = quest.
_eqfUText:
stwu r1, -0x30(r1)
mflr r0
stmw r26, 0x10(r1)
stw r0, 0x34(r1)
mr r31, r3
li r30, 0
li r29, 0
lis r12, _eqfUNames@ha
addi r12, r12, _eqfUNames@l
lwz r11, 0(r12)
addi r10, r12, 4
_eqfUTFind:
cmpwi r11, 0
beq _eqfUTLoop
lwz r9, 0(r10)
cmpw r9, r5
beq _eqfUTHit
addi r10, r10, 0x1C
addi r11, r11, -1
b _eqfUTFind
_eqfUTHit:
slwi r9, r4, 2
addi r9, r9, 4
lwzx r30, r10, r9
cmpwi r30, 0
beq _eqfUTLoop
add r30, r30, r12
_eqfUTLoop:
slwi r28, r29, 2
lwzx r27, r31, r28
mr r3, r27
cmpwi r30, 0
beq _eqfUTLen
mr r3, r30
_eqfUTLen:
li r26, 0
_eqfUTLen2:
lbzx r0, r3, r26
cmpwi r0, 0
beq _eqfUTLenOk
addi r26, r26, 1
b _eqfUTLen2
_eqfUTLenOk:
cmpwi r30, 0
bne _eqfUTAlloc
slwi r26, r26, 1   ; converted text is at most twice as long
_eqfUTAlloc:
lis r12, 0x103D
lwz r12, 0x612C(r12)
lwz r10, 0(r12)
lwz r0, 0x3C(r10)
mtctr r0
mr r3, r12
addi r4, r26, 1
li r5, 0x10
bctrl
stwx r3, r31, r28
cmpwi r30, 0
beq _eqfUTConv
mr r4, r30
li r5, 0x7FFF
bl _eqfUCopyStr
mr r30, r4         ; next language's string
b _eqfUTFree
_eqfUTConv:
mr r4, r27
addi r5, r26, 1
bl _eqfUSjis
_eqfUTFree:
lis r3, 0x103D
lwz r3, 0x612C(r3)
lwz r12, 0(r3)
lwz r0, 0x6C(r12)
mtctr r0
mr r4, r27
bctrl
addi r29, r29, 1
cmpwi r29, 5
blt _eqfUTLoop
lwz r0, 0x34(r1)
mtlr r0
lmw r26, 0x10(r1)
addi r1, r1, 0x30
blr

; Copy a string, at most r5 bytes with its NUL. Returns r4 just past the source NUL.
_eqfUCopyStr:
addi r5, r5, -1
_eqfUCLoop:
lbz r0, 0(r4)
addi r4, r4, 1
cmpwi r0, 0
beq _eqfUCEnd
cmpwi r5, 0
ble _eqfUCLoop
stb r0, 0(r3)
addi r3, r3, 1
addi r5, r5, -1
b _eqfUCLoop
_eqfUCEnd:
stb r0, 0(r3)
blr

; Shift-JIS to UTF-8. r3 = out, r4 = in, r5 = out size with NUL. Kana and full-width ASCII are
; kept, anything the Western font cannot draw becomes a star. Never splits a character.
_eqfUSjis:
addi r5, r5, -1
_eqfUSLoop:
lbz r6, 0(r4)
cmpwi r6, 0
beq _eqfUSEnd
addi r4, r4, 1
cmplwi r6, 0x80
blt _eqfUSOne
cmplwi r6, 0x81
blt _eqfUSStar
cmplwi r6, 0x9F
ble _eqfUSTwo
cmplwi r6, 0xE0
blt _eqfUSStar
cmplwi r6, 0xFC
bgt _eqfUSStar
_eqfUSTwo:
lbz r7, 0(r4)
cmpwi r7, 0
beq _eqfUSStar
addi r4, r4, 1
cmpwi r6, 0x81
beq _eqfUS81
cmpwi r6, 0x82
beq _eqfUS82
cmpwi r6, 0x83
beq _eqfUS83
b _eqfUSStar
_eqfUS81:
li r6, 0x30FB
cmpwi r7, 0x45
beq _eqfUSThree
li r6, 0x30FC
cmpwi r7, 0x5B
beq _eqfUSThree
lis r8, _eqfUPunct@ha
addi r8, r8, _eqfUPunct@l
_eqfUSPunct:
lbz r9, 0(r8)
cmpwi r9, 0
beq _eqfUSStar
lbz r6, 1(r8)
cmpw r9, r7
beq _eqfUSOne
addi r8, r8, 2
b _eqfUSPunct
_eqfUS82:
addi r8, r7, -0x4F
cmplwi r8, 9
bgt _eqfUS82A
addi r6, r8, 0x30
b _eqfUSOne
_eqfUS82A:
addi r8, r7, -0x60
cmplwi r8, 25
bgt _eqfUS82B
addi r6, r8, 0x41
b _eqfUSOne
_eqfUS82B:
addi r8, r7, -0x81
cmplwi r8, 25
bgt _eqfUS82C
addi r6, r8, 0x61
b _eqfUSOne
_eqfUS82C:
addi r8, r7, -0x9F
cmplwi r8, 0x52
bgt _eqfUSStar
addi r6, r8, 0x3041
b _eqfUSThree
_eqfUS83:
addi r8, r7, -0x40
cmplwi r8, 0x3E
bgt _eqfUS83B
addi r6, r8, 0x30A1
b _eqfUSThree
_eqfUS83B:
addi r8, r7, -0x80
cmplwi r8, 0x16
bgt _eqfUSStar
addi r6, r8, 0x30E0
b _eqfUSThree
_eqfUSStar:
li r6, 0x2A
_eqfUSOne:
cmpwi r5, 1
blt _eqfUSEnd
stb r6, 0(r3)
addi r3, r3, 1
addi r5, r5, -1
b _eqfUSLoop
_eqfUSThree:
cmpwi r5, 3
blt _eqfUSEnd
srwi r7, r6, 12
ori r7, r7, 0xE0
stb r7, 0(r3)
srwi r7, r6, 6
clrlwi r7, r7, 26
ori r7, r7, 0x80
stb r7, 1(r3)
clrlwi r7, r6, 26
ori r7, r7, 0x80
stb r7, 2(r3)
addi r3, r3, 3
addi r5, r5, -3
b _eqfUSLoop
_eqfUSEnd:
li r0, 0
stb r0, 0(r3)
blr

; Board summary text. r3 = summary already in the Western layout.
_eqfUBoardText:
stwu r1, -0x20(r1)
mflr r0
stw r0, 0x24(r1)
stw r29, 0x14(r1)
stw r30, 0x18(r1)
stw r31, 0x1C(r1)
mr r31, r3
li r29, 0
li r30, 0
lbz r5, 0x96(r31)
lbz r6, 0x97(r31)
slwi r6, r6, 8
or r5, r5, r6
lis r12, _eqfUNames@ha
addi r12, r12, _eqfUNames@l
lwz r11, 0(r12)
addi r10, r12, 4
_eqfUBFind:
cmpwi r11, 0
beq _eqfUBGo
lwz r9, 0(r10)
cmpw r9, r5
beq _eqfUBHit
addi r10, r10, 0x1C
addi r11, r11, -1
b _eqfUBFind
_eqfUBHit:
lwz r29, 4(r10)
lwz r30, 8(r10)
add r29, r29, r12
add r30, r30, r12
_eqfUBGo:
mr r3, r31
li r4, 0x1E
mr r5, r29
bl _eqfUBField
addi r3, r31, 0x98
li r4, 0x3E
mr r5, r30
bl _eqfUBField
lwz r0, 0x24(r1)
mtlr r0
lwz r29, 0x14(r1)
lwz r30, 0x18(r1)
lwz r31, 0x1C(r1)
addi r1, r1, 0x20
blr

; r3 = five fixed slots, r4 = slot size, r5 = five strings from the table, or 0 to convert slot 0.
; The table is in file order (eng fre ger ita spa); the summary's slots are in the game's
; language order (eng fre spa ger ita), so file string k goes to slot _eqfUBSlot[k].
_eqfUBField:
stwu r1, -0x70(r1)
mflr r0
stw r0, 0x74(r1)
stmw r27, 0x5C(r1)
mr r31, r3
mr r30, r4
mr r29, r5
li r28, 0
cmpwi r29, 0
bne _eqfUBLoop
addi r3, r1, 0x10
mr r4, r31
mr r5, r30
bl _eqfUSjis
_eqfUBLoop:
lis r12, _eqfUBSlot@ha
addi r12, r12, _eqfUBSlot@l
lbzx r0, r12, r28
mullw r0, r0, r30
add r3, r31, r0
mr r5, r30
cmpwi r29, 0
beq _eqfUBTmp
mr r4, r29
bl _eqfUCopyStr
mr r29, r4
b _eqfUBNext
_eqfUBTmp:
addi r4, r1, 0x10
bl _eqfUCopyStr
_eqfUBNext:
addi r28, r28, 1
cmpwi r28, 5
blt _eqfUBLoop
lwz r0, 0x74(r1)
mtlr r0
lmw r27, 0x5C(r1)
addi r1, r1, 0x70
