0x02076D70 = bl _eqfUName
0x02076D8C = bl _eqfUMore
0x02076DB4 = bl _eqfUMore
0x02076DD0 = bl _eqfUMore
0x02076E04 = bl _eqfUMore
0x02076E14 = bl _eqfUMore
0x0224E920 = bl _eqfUBoard


[MH3U_EventQuestFix_EU_v32]
moduleMatches = 0xADA406E7

; Same as the US group. The EU reader's string helper 0x02076B70 reads five strings per text
; field, so a JP record (one string per field) is misread and the quest is lost: the lookup
; by number then returns null and the quest setup crashes. This replaces the helper at its six
; call sites. After the title, the same two bytes tell the layouts apart. On a JP record the
; one string is read and copied into all five language slots (each slot is freed on its own,
; so each needs its own allocation).
.origin = codecave

_eqfEState:
.uint 0            ; +0 the reader object of the record being parsed
.uint 0            ; +4 1 = that record is in the JP layout
.uint 0            ; +8 next text field
.uint 0            ; +C quest number

_eqfEName:
li r6, 1
b _eqfEStrs
_eqfEMore:
li r6, 0
_eqfEStrs:
stwu r1, -0x30(r1)
mflr r0
stmw r25, 0xC(r1)
stw r0, 0x34(r1)
mr r31, r5         ; reader
mr r29, r4         ; the five string slots
mr r26, r6         ; 1 = title field
li r28, 0          ; language
li r25, 0          ; 1 = JP layout
_eqfELoop:
cmpwi r28, 0
beq _eqfELen
cmpwi r25, 0
bne _eqfEAlloc     ; JP layout: same length as the first string
_eqfELen:
lwz r8, 0x14(r31)
lwz r9, 0x1C(r8)
mtctr r9
mr r3, r31
bctrl
mr r30, r3
_eqfEAlloc:
lis r12, 0x103D
lwz r12, 0x612C(r12)
lwz r10, 0(r12)
lwz r0, 0x3C(r10)
mtctr r0
mr r3, r12
li r5, 0x10
addi r4, r30, 1
bctrl
slwi r27, r28, 2
stwx r3, r29, r27
cmpwi r28, 0
beq _eqfERead
cmpwi r25, 0
beq _eqfERead
lwz r7, 0(r29)     ; JP layout: copy the first string
li r9, 0
_eqfECopy:
cmpw r9, r30
bge _eqfEEnd
lbzx r0, r7, r9
stbx r0, r3, r9
addi r9, r9, 1
b _eqfECopy
_eqfERead:
mr r4, r3
mr r3, r31
mr r5, r30
bl 0x02D93E88
_eqfEEnd:
lwzx r6, r29, r27
li r0, 0
stbx r0, r6, r30
cmpwi r28, 0
bne _eqfENext
lis r12, _eqfEState@ha
addi r12, r12, _eqfEState@l
cmpwi r26, 0
beq _eqfEKnown
li r0, 0
lwz r10, 8(r31)    ; read position
lwz r11, 0xC(r31)  ; end of buffered data
addi r9, r10, 4
cmplw r9, r11
bgt _eqfEStore
lwz r9, 4(r31)     ; buffer
add r9, r9, r10
lhz r8, 2(r9)
cmpwi r8, 0
beq _eqfEStore     ; high half of the next length = Western
lbz r7, 0(r9)      ; quest number, little endian
lbz r8, 1(r9)
slwi r8, r8, 8
or r7, r7, r8
stw r7, 0xC(r12)
li r8, 0
stw r8, 8(r12)
li r0, 1
_eqfEStore:
stw r31, 0(r12)
stw r0, 4(r12)
_eqfEKnown:
lwz r0, 0(r12)
cmplw r0, r31
bne _eqfENext
lwz r25, 4(r12)
_eqfENext:
addi r28, r28, 1
cmpwi r28, 5
blt _eqfELoop
cmpwi r25, 0
beq _eqfEExit
lis r12, _eqfEState@ha
addi r12, r12, _eqfEState@l
lwz r4, 8(r12)
addi r0, r4, 1
stw r0, 8(r12)
lwz r5, 0xC(r12)
mr r3, r29
bl _eqfEText
_eqfEExit:
lwz r0, 0x34(r1)
mtlr r0
lmw r25, 0xC(r1)
addi r1, r1, 0x30
blr

; Board summary: a JP host sends 1 title + 1 objective, this game expects 5 + 5.
; r3 = summary in wire order, its quest number is at r3-4.
_eqfEBoard:
lhz r5, -4(r3)
lhz r6, 0x96(r3)
cmplw r6, r5
beq _eqfEBoardGo
lhz r6, 0x1E(r3)
cmplw r6, r5
bne _eqfEBoardGo
lhz r6, 0x5E(r3)
lhz r7, 0x9E(r3)
lhz r8, 0xDE(r3)
lhz r9, 0xE0(r3)
lhz r10, 0xE2(r3)
lhz r11, 0x1DE(r3)
li r0, 0
stb r0, 0x1D(r3)
stb r0, 0x5D(r3)
li r0, 0x3E
mtctr r0
addi r4, r3, 0x1F
addi r12, r3, 0x97
_eqfEBoardObj:
lbzu r0, 1(r4)
stbu r0, 1(r12)
bdnz _eqfEBoardObj
li r0, 0xF8
mtctr r0
addi r4, r3, 0x97
addi r12, r3, 0xD5
_eqfEBoardObj2:
lbzu r0, 1(r4)
stbu r0, 1(r12)
bdnz _eqfEBoardObj2
li r0, 0x78
mtctr r0
addi r4, r3, -1
addi r12, r3, 0x1D
_eqfEBoardTitle:
lbzu r0, 1(r4)
stbu r0, 1(r12)
bdnz _eqfEBoardTitle
sth r5, 0x96(r3)
sth r6, 0x1CE(r3)
sth r7, 0x1D0(r3)
sth r8, 0x1D2(r3)
sth r9, 0x1D4(r3)
sth r10, 0x1D6(r3)
sth r11, 0x1D8(r3)
mflr r0
stwu r1, -0x10(r1)
stw r0, 0x14(r1)
stw r3, 8(r1)
bl _eqfEBoardText
lwz r3, 8(r1)
lwz r0, 0x14(r1)
mtlr r0
addi r1, r1, 0x10
_eqfEBoardGo:
b 0x02059C48


; Replace a JP record's text with the Western text for that quest number, or with a UTF-8
; conversion. r3 = the five language slots (each holds the JP string), r4 = field, r5 = quest.
_eqfEText:
stwu r1, -0x30(r1)
mflr r0
stmw r26, 0x10(r1)
stw r0, 0x34(r1)
mr r31, r3
li r30, 0
li r29, 0
lis r12, _eqfENames@ha
addi r12, r12, _eqfENames@l
lwz r11, 0(r12)
addi r10, r12, 4
_eqfETFind:
cmpwi r11, 0
beq _eqfETLoop
lwz r9, 0(r10)
cmpw r9, r5
beq _eqfETHit
addi r10, r10, 0x1C
addi r11, r11, -1
b _eqfETFind
_eqfETHit:
slwi r9, r4, 2
addi r9, r9, 4
lwzx r30, r10, r9
cmpwi r30, 0
beq _eqfETLoop
add r30, r30, r12
_eqfETLoop:
slwi r28, r29, 2
lwzx r27, r31, r28
mr r3, r27
cmpwi r30, 0
beq _eqfETLen
mr r3, r30
_eqfETLen:
li r26, 0
_eqfETLen2:
lbzx r0, r3, r26
cmpwi r0, 0
beq _eqfETLenOk
addi r26, r26, 1
b _eqfETLen2
_eqfETLenOk:
cmpwi r30, 0
bne _eqfETAlloc
slwi r26, r26, 1   ; converted text is at most twice as long
_eqfETAlloc:
lis r12, 0x103D
lwz r12, 0x612C(r12)
lwz r10, 0(r12)
lwz r0, 0x3C(r10)
mtctr r0
mr r3, r12
addi r4, r26, 1
li r5, 0x10
bctrl
stwx r3, r31, r28
cmpwi r30, 0
beq _eqfETConv
mr r4, r30
li r5, 0x7FFF
bl _eqfECopyStr
mr r30, r4         ; next language's string
b _eqfETFree
_eqfETConv:
mr r4, r27
addi r5, r26, 1
bl _eqfESjis
_eqfETFree:
lis r3, 0x103D
lwz r3, 0x612C(r3)
lwz r12, 0(r3)
lwz r0, 0x6C(r12)
mtctr r0
mr r4, r27
bctrl
addi r29, r29, 1
cmpwi r29, 5
blt _eqfETLoop
lwz r0, 0x34(r1)
mtlr r0
lmw r26, 0x10(r1)
addi r1, r1, 0x30
blr

; Copy a string, at most r5 bytes with its NUL. Returns r4 just past the source NUL.
_eqfECopyStr:
addi r5, r5, -1
_eqfECLoop:
lbz r0, 0(r4)
addi r4, r4, 1
cmpwi r0, 0
beq _eqfECEnd
cmpwi r5, 0
ble _eqfECLoop
stb r0, 0(r3)
addi r3, r3, 1
addi r5, r5, -1
b _eqfECLoop
_eqfECEnd:
stb r0, 0(r3)
blr

; Shift-JIS to UTF-8. r3 = out, r4 = in, r5 = out size with NUL. Kana and full-width ASCII are
; kept, anything the Western font cannot draw becomes a star. Never splits a character.
_eqfESjis:
addi r5, r5, -1
_eqfESLoop:
lbz r6, 0(r4)
cmpwi r6, 0
beq _eqfESEnd
addi r4, r4, 1
cmplwi r6, 0x80
blt _eqfESOne
cmplwi r6, 0x81
blt _eqfESStar
cmplwi r6, 0x9F
ble _eqfESTwo
cmplwi r6, 0xE0
blt _eqfESStar
cmplwi r6, 0xFC
bgt _eqfESStar
_eqfESTwo:
lbz r7, 0(r4)
cmpwi r7, 0
beq _eqfESStar
addi r4, r4, 1
cmpwi r6, 0x81
beq _eqfES81
cmpwi r6, 0x82
beq _eqfES82
cmpwi r6, 0x83
beq _eqfES83
b _eqfESStar
_eqfES81:
li r6, 0x30FB
cmpwi r7, 0x45
beq _eqfESThree
li r6, 0x30FC
cmpwi r7, 0x5B
beq _eqfESThree
lis r8, _eqfEPunct@ha
addi r8, r8, _eqfEPunct@l
_eqfESPunct:
lbz r9, 0(r8)
